# Specify the LCA model formula # Include only outcome variables in the main formula # No covariates yet, just latent classes (indicator variables)
lcm_formula <- cbind( carFuelP_cat1, carMainP_cat1, taxiP_cat1, busP_cat1, trainP_cat1, airP_cat1, microP_cat1 ) ~ 1
#adding covariates # final_formula <- update(lcm_formula, . ~ . #+ city_type_rural # + income_less_50k + income_50k_to_75k + income_75k_to_100k # + age_ref_18_to_34 + age_ref_35_to_44 + age_ref_45_to_54 # # + region_midwest + region_south + region_wes # + edu_masters_doctorate + edu_bachelors # + fam_single_mom + fam_single_dad + fam_single_person # + fam_married_all_kids_less_6 + fam_married_oldest_kid_between_6_18 + fam_married_oldest_kid_more_17 # + as.factor(Man_cat1) + as.factor(House_cat1) + as.factor(Food_cat1) + as.factor(Lei_cat1) # + SchoolY # # ) ##USE THIS ONEEEEE final_formula <- update(lcm_formula, . ~ . + city_type_rural + income_less_50k + age_ref_18_to_34 + age_ref_35_to_44 + age_ref_45_to_54 + region_midwest + region_south + region_wes + edu_masters_doctorate + edu_bachelors # + single_kids + married_no_kids + married_kids # + single_no_kids_no_65 + single_no_kids_65 # + married_no_kids_no_65 + married_no_kids_65 # + married_kids_no_65 + married_kids_65 + cu_size_2 + cu_size_3_to_6 + cu_size_more_6 + as.factor(Man_cat1) + as.factor(House_cat1) + as.factor(Food_cat1) + as.factor(Lei_cat1)
)
#sjmisc::frq(x=lcm_data[c("city_type_rural")], out="viewer")
set.seed(123) # Ensure reproducibility model_results <- list() for (n in 2:3) { model_results[[n]] <- poLCA(final_formula, lcm_data, nclass = n, na.rm = TRUE, maxiter = 5000, verbose = FALSE) }
# for (n in 2:3) { # print(model_results[[n]]$Chisq) # print(model_results[[n]]$Gsq) # print(model_results[[n]]$aic) # print(model_results[[n]]$bic) # }
# print(model_results[[3]])
# Extract posterior probabilities for the 4-class model posterior_probs <- model_results[[3]]$posterior
# Add posterior probabilities and latent class assignments to the data lcm_data_with_probs <- cbind(lcm_data, posterior_probs) lcm_data_with_probs$assigned_class <- apply(posterior_probs, 1, which.max)
# Define a function for weighted mean and variance weighted_summary <- function(data, weights) { weighted_mean <- sum(data * weights) / sum(weights) weighted_var <- sum(weights * (data - weighted_mean)^2) / sum(weights) c(mean = weighted_mean, variance = weighted_var) }
# Covariates to summarize covariates <- c("city_type_rural", "income_less_50k", "income_50k_to_75k", "income_75k_to_100k", "age_ref_18_to_34", "age_ref_35_to_44", "age_ref_45_to_54", "region_midwest", "region_south", "region_wes", "edu_masters_doctorate", "edu_bachelors", "fam_single_mom", "fam_single_dad", "fam_single_person", "fam_married_all_kids_less_6", "fam_married_oldest_kid_between_6_18", "fam_married_oldest_kid_more_17", "Man_cat1", "House_cat1", "Food_cat1", "Lei_cat1", "SchoolY" )
# Initialize a list to store results class_summaries <- list()
# Loop through each class for (class in 1:3) { # Subset data for the current class weights <- posterior_probs[, class]
# Compute weighted summary for each covariate summaries <- sapply(covariates, function(cov) { weighted_summary(as.numeric(lcm_data_with_probs[[cov]]), weights) })
# Store results class_summaries[[class]] <- summaries }
# Convert results to a more readable format class_summaries_df <- lapply(class_summaries, function(x) { t(as.data.frame(x)) }) names(class_summaries_df) <- paste("Class", 1:3)
# Print summaries for each class for (class in 1:3) { cat("\nSummary Statistics for Class", class, ":\n") print(class_summaries_df[[class]]) }

model_3 <- model_results[[3]]
# creating tables for excel create_probs_table <- function(model, percent = FALSE, lcm_data){ mult <- ifelse(percent, 100, 1) rnd <- ifelse(percent, 2, 4)
df_totals <- matrix(model$P * mult) |> round(rnd) |> t() |> as.data.frame()
names(df_totals) <- paste0("class_",c(1:ncol(df_totals))) df_totals$variable <- "Class Probablilty"
probs <- model$probs df_list <- list() for (var_name in names(probs)){ mtx <- probs[[var_name]]
df <- as.data.frame(round(t(mtx * mult),rnd))
names(df) <- paste0("class_",c(1:ncol(df))) row.names(df) <- NULL
df$variable <- var_name df$level <- 1:nrow(df)
df_list[[var_name]] <- df }
combined_df <- bind_rows(df_list) combined_df <- bind_rows(df_totals, combined_df)
level_meaning <- "NA" for (row_num in 2:nrow(combined_df)){
col_str <- gsub("1","",combined_df[[row_num,"variable"]]) new_df <- lcm_data[lcm_data[[paste0(col_str,"1")]] == combined_df[[row_num,"level"]],grep(col_str,names(lcm_data))] meaning <- new_df[[gsub("1","",names(new_df)[[1]])]][[1]] |> as.character()
level_meaning <- c(level_meaning, meaning) }
combined_df$level_def <- level_meaning
combined_df <- combined_df |> dplyr::select(!level) |> dplyr::select(any_of(c("variable","level_def",names(combined_df))))
return(combined_df) }
create_regr_tbl <- function(model){
coeffs <- model$coeff se <- model$coeff.se tval <- coeffs / se
df <- data.frame(exogenous_var = row.names(coeffs)) df[[paste0("coeff_",1)]] <- round(coeffs[,1], 3) df[[paste0("t_stat_",1)]] <- round(tval[,1], 3)
if (ncol(coeffs) < 2){ return(df) }
for (i in 2:ncol(coeffs)){ new_df <- data.frame(exogenous_var = row.names(coeffs)) new_df[[paste0("coeff_",i)]] <- round(coeffs[,i], 3) new_df[[paste0("t_stat_",i)]] <- round(tval[,i], 3)
df <- left_join(df, new_df, by = "exogenous_var") }
return(df)
}
